/**
 * `data/icons/wowIcons.json` — GENERATED by `python -m scripts.wow_icons.build`.
 * `items`: item id -> `[icon file id, quality]` (quality 0 = poor … 7 = heirloom).
 * `spells`: spell id -> icon file id.
 */
export interface WowIconFile {
  source: string;
  /** The client build the icons were published for — part of every icon URL. */
  build: string;
  items: Record<string, number[]>;
  spells: Record<string, number>;
}
